* { box-sizing: border-box; }
:root {
  color-scheme: light;
  --ink: #23313a;
  --muted: #607078;
  --paper: #fffdf8;
  --coral: #ef7869;
  --blue: #4f91bc;
  --gold: #eabf52;
}
body {
  min-height: 100vh;
  margin: 0;
  padding: 28px 16px;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at 50% 0%, #fff9e9 0, #f4f0e8 68%);
  color: var(--ink);
  font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
.card {
  width: min(100%, 470px);
  padding: clamp(22px, 6vw, 36px);
  border: 1px solid #e6dfd2;
  border-radius: 24px;
  background: var(--paper);
  box-shadow: 0 18px 50px #34414b18;
  text-align: center;
}
.eyebrow { margin: 0 0 4px; color: #a16d48; font-size: 0.85rem; font-weight: 750; letter-spacing: .11em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(1.8rem, 7vw, 2.3rem); line-height: 1.15; letter-spacing: -.04em; }
.intro { max-width: 330px; margin: 12px auto 22px; color: var(--muted); }
.status { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 14px; text-align: left; }
.status p { margin: 0; }
.status strong { display: inline-grid; min-width: 2rem; min-height: 2rem; margin-left: 5px; place-items: center; border-radius: 10px; background: #f3eee4; }
#message { color: #607078; font-weight: 650; text-align: right; }
.board {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
  width: min(100%, 350px);
  aspect-ratio: 1;
  margin: 0 auto 22px;
  padding: 8px;
  border-radius: 16px;
  background: #eee8dc;
}
.cell { min-width: 0; border: 0; border-radius: 7px; box-shadow: inset 0 1px 2px #17202a20; transition: background-color 160ms ease, transform 120ms ease; }
.cell[data-color="coral"], .color-button[data-color="coral"] span { background: var(--coral); }
.cell[data-color="blue"], .color-button[data-color="blue"] span { background: var(--blue); }
.cell[data-color="gold"], .color-button[data-color="gold"] span { background: var(--gold); }
.palette { min-width: 0; margin: 0; padding: 0; border: 0; }
legend { margin: 0 auto 10px; color: var(--muted); font-size: .95rem; font-weight: 650; }
.color-options { display: flex; justify-content: center; gap: 10px; }
.color-button, .reset-button {
  min-height: 48px;
  border: 1px solid #d9d4ca;
  border-radius: 12px;
  background: #fff;
  color: var(--ink);
  font: inherit;
  font-weight: 650;
  cursor: pointer;
  transition: transform 120ms ease, box-shadow 120ms ease, border-color 120ms ease, background 120ms ease;
}
.color-button { display: inline-flex; align-items: center; gap: 8px; padding: 8px 13px; }
.color-button span { width: 20px; height: 20px; border-radius: 6px; }
.color-button:hover, .reset-button:hover { border-color: #9ca6a5; background: #fbfaf6; }
.color-button[aria-pressed="true"] { border-color: var(--ink); box-shadow: 0 0 0 2px var(--paper), 0 0 0 4px var(--ink); }
.color-button:active, .reset-button:active { transform: translateY(2px) scale(.98); }
button:focus-visible { outline: 3px solid #23313a; outline-offset: 3px; }
.reset-button { margin-top: 18px; padding: 8px 18px; }
@media (max-width: 380px) { .board { gap: 4px; padding: 6px; } .color-options { gap: 7px; } .color-button { gap: 6px; padding: 7px 9px; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition-duration: .01ms !important; } }

(() => {
  const initial = [
    ['coral','blue','blue','gold','gold','coral'],
    ['coral','coral','blue','gold','coral','coral'],
    ['blue','coral','gold','gold','blue','coral'],
    ['blue','blue','gold','coral','blue','blue'],
    ['gold','blue','coral','coral','gold','blue'],
    ['gold','gold','coral','blue','blue','gold']
  ];
  const board = document.querySelector('#board');
  const moveCount = document.querySelector('#moves');
  const message = document.querySelector('#message');
  const colorButtons = [...document.querySelectorAll('.color-button')];
  let cells = [];
  let moves = 0;
  let finished = false;

  function render() {
    board.replaceChildren();
    cells = initial.map(row => [...row]);
    cells.forEach((row, r) => row.forEach((color, c) => {
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.setAttribute('role', 'gridcell');
      cell.setAttribute('aria-label', `Row ${r + 1}, column ${c + 1}: ${color}`);
      cell.dataset.color = color;
      board.append(cell);
    }));
    moves = 0;
    finished = false;
    moveCount.textContent = '0';
    message.textContent = 'Pick a color to begin.';
    colorButtons.forEach(button => button.setAttribute('aria-pressed', 'false'));
  }

  function fill(target) {
    if (finished || target === cells[0][0]) return;
    const source = cells[0][0];
    const stack = [[0, 0]];
    const visited = new Set();
    while (stack.length) {
      const [r, c] = stack.pop();
      const key = `${r},${c}`;
      if (r < 0 || r >= 6 || c < 0 || c >= 6 || visited.has(key) || cells[r][c] !== source) continue;
      visited.add(key);
      cells[r][c] = target;
      stack.push([r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]);
    }
    moves++;
    moveCount.textContent = String(moves);
    [...board.children].forEach((cell, index) => {
      const r = Math.floor(index / 6), c = index % 6;
      cell.dataset.color = cells[r][c];
      cell.setAttribute('aria-label', `Row ${r + 1}, column ${c + 1}: ${cells[r][c]}`);
    });
    finished = cells.every(row => row.every(color => color === target));
    message.textContent = finished ? 'One color!' : `Filled with ${target}. Choose again.`;
  }

  colorButtons.forEach(button => button.addEventListener('click', () => {
    colorButtons.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
    fill(button.dataset.color);
  }));
  document.querySelector('#reset').addEventListener('click', render);
  render();
})();
